import { MakeLogicType, actions, events, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api, { ApiConfig } from 'lib/api'

import { cohortsCalculationHistoryRetrieve } from 'products/cohorts/frontend/generated/api'
import type {
    CohortCalculationHistoryApi,
    CohortCalculationHistoryResponseApi,
} from 'products/cohorts/frontend/generated/api.schemas'

import type { CohortType } from '../../types'

export interface CohortCalculationHistorySceneLogicProps {
    cohortId: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cohortCalculationHistorySceneLogicValues {
    calculationHistory: CohortCalculationHistoryApi[]
    calculationHistoryResponse: CohortCalculationHistoryResponseApi
    calculationHistoryResponseLoading: boolean
    cohort: any
    cohortLoading: boolean
    cohortMissing: boolean
    limit: number
    page: number
    totalRecords: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cohortCalculationHistorySceneLogicActions {
    loadCalculationHistory: (_: any) => any
    loadCalculationHistoryFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCalculationHistorySuccess: (
        calculationHistoryResponse: CohortCalculationHistoryResponseApi,
        payload?: any
    ) => {
        calculationHistoryResponse: CohortCalculationHistoryResponseApi
        payload?: any
    }
    loadCohort: (_: any) => any
    loadCohortFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCohortSuccess: (
        cohort: CohortType | null,
        payload?: any
    ) => {
        cohort: CohortType | null
        payload?: any
    }
    setCohortMissing: () => {
        value: true
    }
    setLimit: (limit: number) => {
        limit: number
    }
    setPage: (page: number) => {
        page: number
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cohortCalculationHistorySceneLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        calculationHistory: (
            calculationHistoryResponse: CohortCalculationHistoryResponseApi
        ) => CohortCalculationHistoryApi[]
        totalRecords: (calculationHistoryResponse: CohortCalculationHistoryResponseApi) => number
    }
}

export type cohortCalculationHistorySceneLogicType = MakeLogicType<
    cohortCalculationHistorySceneLogicValues,
    cohortCalculationHistorySceneLogicActions,
    CohortCalculationHistorySceneLogicProps,
    cohortCalculationHistorySceneLogicMeta
>

export const cohortCalculationHistorySceneLogic = kea<cohortCalculationHistorySceneLogicType>([
    props({} as CohortCalculationHistorySceneLogicProps),
    key(({ cohortId }) => String(cohortId)),
    path((key) => ['scenes', 'cohorts', 'cohortCalculationHistorySceneLogic', key]),

    actions({
        setPage: (page: number) => ({ page }),
        setLimit: (limit: number) => ({ limit }),
        setCohortMissing: true,
    }),

    loaders(({ props, actions, values }) => ({
        calculationHistoryResponse: [
            { results: [], count: 0, next: null, previous: null } as CohortCalculationHistoryResponseApi,
            {
                loadCalculationHistory: async (_, breakpoint) => {
                    if (!props.cohortId || props.cohortId <= 0) {
                        return { results: [], count: 0, next: null, previous: null }
                    }
                    breakpoint()
                    try {
                        const offset = (values.page - 1) * values.limit
                        return await cohortsCalculationHistoryRetrieve(
                            String(ApiConfig.getCurrentProjectId()),
                            props.cohortId,
                            {
                                limit: values.limit,
                                offset,
                            }
                        )
                    } catch (error: any) {
                        if (error.status === 404) {
                            actions.setCohortMissing()
                        }
                        throw error
                    }
                },
            },
        ],
        cohort: [
            null as any,
            {
                loadCohort: async (_, breakpoint) => {
                    if (!props.cohortId || props.cohortId <= 0) {
                        return null
                    }
                    breakpoint()
                    try {
                        return await api.cohorts.get(props.cohortId)
                    } catch {
                        actions.setCohortMissing()
                        return null
                    }
                },
            },
        ],
    })),

    reducers({
        page: [
            1,
            {
                setPage: (_, { page }) => page,
            },
        ],
        limit: [
            100,
            {
                setLimit: (_, { limit }) => limit,
            },
        ],
        cohortMissing: [
            false,
            {
                setCohortMissing: () => true,
            },
        ],
    }),

    listeners(({ actions }) => ({
        setPage: () => {
            actions.loadCalculationHistory({})
        },
        setLimit: () => {
            actions.loadCalculationHistory({})
        },
    })),

    selectors({
        calculationHistory: [
            (s) => [s.calculationHistoryResponse],
            (response: CohortCalculationHistoryResponseApi): CohortCalculationHistoryApi[] => response.results,
        ],
        totalRecords: [
            (s) => [s.calculationHistoryResponse],
            (response: CohortCalculationHistoryResponseApi): number => response.count,
        ],
    }),

    events(({ actions, props }) => ({
        afterMount: () => {
            if (props.cohortId && props.cohortId > 0) {
                actions.loadCalculationHistory({})
                actions.loadCohort({})
            }
        },
    })),
])
